from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    results = []

    if kind == "DAILY":
        current = start_date
        for _ in range(count):
            results.append(current.isoformat())
            current += timedelta(days=interval)
        return results

    if kind == "WEEKLY":
        weekday_numbers = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                           "FR": 4, "SA": 5, "SU": 6}
        weekdays = sorted(weekday_numbers[day] for day in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())
        week_index = 0
        while len(results) < count:
            if week_index % interval == 0:
                for weekday in weekdays:
                    current = week_start + timedelta(days=week_index * 7 + weekday)
                    if current >= start_date:
                        results.append(current.isoformat())
                        if len(results) == count:
                            return results
            week_index += 1
        return results

    if kind == "MONTHLY":
        month_index = 0
        year, month = start_date.year, start_date.month
        while len(results) < count:
            if month_index % interval == 0:
                last_day = calendar.monthrange(year, month)[1]
                if len(parts) == 3:
                    day = int(parts[2])
                    day = last_day if day == -1 else day
                    if day <= last_day:
                        current = date(year, month, day)
                        if current >= start_date:
                            results.append(current.isoformat())
                else:
                    occurrence = int(parts[2])
                    weekday = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                               "FR": 4, "SA": 5, "SU": 6}[parts[3]]
                    matching_days = [
                        day for day in range(1, last_day + 1)
                        if date(year, month, day).weekday() == weekday
                    ]
                    index = occurrence - 1 if occurrence > 0 else -1
                    if len(matching_days) >= occurrence if occurrence > 0 else matching_days:
                        current = date(year, month, matching_days[index])
                        if current >= start_date:
                            results.append(current.isoformat())

            month_index += 1
            year, month = divmod(start_date.month - 1 + month_index, 12)
            year += start_date.year
            month += 1
        return results

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year_offset = 0
        while len(results) < count:
            year = start_date.year + year_offset
            try:
                current = date(year, month, day)
            except ValueError:
                current = None
            if current is not None and current >= start_date:
                results.append(current.isoformat())
            year_offset += interval
        return results

    return results
